// Reinterpret float as raw unsigned integer bits (IEEE 754)
union BitwiseView {
    float f_val;
    unsigned int u_val;
};

// Data structure sharing memory
BitwiseView view;

// Write to one member
view.f_val = 123.45f;

// Read the safe alternative member (valid C/C++)
unsigned int raw_bits = view.u_val;

// Classic alternative for byte inspection (endianness)
union ByteInspector {
    int integer;
    unsigned char bytes[sizeof(int)];
};

ByteInspector b_view;
b_view.integer = 0xDEADBEEF;

unsigned char byte0 = b_view.bytes[0]; // Byte 0
unsigned char byteN = b_view.bytes[3]; // Byte N
